from pathlib import Path
import hashlib,json
p=Path("candidate/MainForm.cs")
s=p.read_text(encoding="utf-8-sig")
old="    private async void MainForm_FormClosing(object? sender, FormClosingEventArgs e)\n    {\n        if (automaticBackupCompleted || automaticBackupRunning) return;\n        automaticBackupRunning = true;\n        e.Cancel = true;\n        try\n        {\n            using var timeout = new CancellationTokenSource(TimeSpan.FromSeconds(30));\n            await DatabaseBackupService.CreateAndSendAsync(timeout.Token);\n        }\n        catch(Exception ex)\n        {\n            try\n            {\n                Directory.CreateDirectory(Database.BackupFolder);\n                await File.AppendAllTextAsync(Path.Combine(Database.BackupFolder, \"backup-errors.log\"),\n                    $\"[{DateTime.Now:yyyy-MM-dd HH:mm:ss}] {ex}\\n\");\n            }\n            catch { }\n        }\n        finally\n        {\n            automaticBackupCompleted = true;\n            automaticBackupRunning = false;\n            BeginInvoke(Close);\n        }\n    }\n"
new="    private async void MainForm_FormClosing(object? sender, FormClosingEventArgs e)\n    {\n        if (automaticBackupCompleted) return;\n        // Every close request must remain cancelled until the one backup finishes.\n        e.Cancel = true;\n        if (automaticBackupRunning) return;\n        automaticBackupRunning = true;\n        var wasEnabled = Enabled;\n        Enabled = false;\n        UseWaitCursor = true;\n        try\n        {\n            // Leave the first FormClosing invocation before a synchronous backup can finish.\n            await Task.Yield();\n            using var timeout = new CancellationTokenSource(TimeSpan.FromSeconds(30));\n            await DatabaseBackupService.CreateAndSendAsync(timeout.Token);\n        }\n        catch(Exception ex)\n        {\n            try\n            {\n                Directory.CreateDirectory(Database.BackupFolder);\n                await File.AppendAllTextAsync(Path.Combine(Database.BackupFolder, \"backup-errors.log\"),\n                    $\"[{DateTime.Now:yyyy-MM-dd HH:mm:ss}] {ex}\\n\");\n            }\n            catch { }\n        }\n        finally\n        {\n            automaticBackupCompleted = true;\n            automaticBackupRunning = false;\n            // The await resumes on the UI thread. Never queue work on a destroyed handle.\n            if (!IsDisposed && !Disposing && IsHandleCreated)\n            {\n                UseWaitCursor = false;\n                Enabled = wasEnabled;\n                Close();\n            }\n        }\n    }\n"
assert s.count(old)==1,"Unknown closing implementation; refuse patch"
before=s
s=s.replace(old,new)
p.write_text(s,encoding="utf-8")
assert s.replace(new,old)==before
Path("evidence/logon-scope.json").write_text(json.dumps(dict(Pass=True,OnlyMethod="MainForm_FormClosing",Channel="001",BeforeSha256=hashlib.sha256(before.encode()).hexdigest(),AfterSha256=hashlib.sha256(s.encode()).hexdigest(),Published=False),indent=2))
# Exercise the exact handler extracted from the reconstructed production source.
Path("logon-probe/Handler.cs").write_text("using System;\nusing System.IO;\nusing System.Threading;\nusing System.Threading.Tasks;\nusing System.Windows.Forms;\npartial class CloseProbe : Form { bool automaticBackupCompleted, automaticBackupRunning; public CloseProbe(){FormClosing += MainForm_FormClosing;}\n"+new+"\n}")
